llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Alfentanil, the closest structural analogue sharing the N-phenylpropanamide piperidine core, has baseline absolute oral bioavailability of 0.45 ± 0.09 in healthy subjects, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Fentanyl, a close analogue with the same anilide-piperidine scaffold and an N-phenethyl-like substituent, has oral bioavailability of 0.32 ± 0.1, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Alfentanil absolute oral bioavailability was 0.42 ± 0.15 in volunteers, independently confirming moderate-to-high oral absorption for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Phenoperidine, a lower-similarity 4-phenylpiperidine opioid, had systemic bioavailability of only 9.9%, providing contradictory evidence but with lower transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Tilidine, a structurally distant opioid, has systemic availability of about 3%, but its extensive first-pass metabolism and low similarity limit transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C31"],
      "claim": "Loperamide has very low oral bioavailability (0.3%) driven by P-gp efflux, a liability not evident in the query's alfentanil-like scaffold, so its contradictory weight is limited.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogues alfentanil and fentanyl have human oral bioavailability values of roughly 30-45%, clearly above the 20% threshold. Lower-similarity opioids with low oral bioavailability involve distinct metabolic or efflux liabilities and are less transferable. Therefore the query is predicted to have high oral bioavailability (F ≥ 20%).",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the exact query molecule.",
    "One alfentanil record (C44) reports 1% oral bioavailability, conflicting with multiple other alfentanil measurements; its reliability is uncertain.",
    "Rifampin-interaction alfentanil records reflect enzyme induction and are not baseline bioavailability evidence.",
    "Human pharmacokinetic data for the thiophene-containing fentanyl/alfentanil analog are lacking."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

